Vue.component("cmty-data-fetcher",{template:"#cmty-data-fetcher-tpl",props:["communityId"],methods:{fetchCommunityData:function fetchCommunityData(){this.$store.dispatch("setCmtyPageData",this.communityId)}},created:function created(){if(this.communityId)this.fetchCommunityData();else var commIdWatcher=this.$watch("communityId",(function(newVal){newVal&&(this.fetchCommunityData(),commIdWatcher())}))}});